import sys

def split_tips(total_tips, servers_hours):
    """Split tips across servers by hours worked, rounded to cents.
    servers_hours: dict of server -> hours. Returns dict server -> tip share.
    Rounding remainder goes to the largest share so the sum equals total_tips exactly."""
    cents = round(total_tips * 100)
    hours = sum(servers_hours.values())
    if hours <= 0:
        raise ValueError("no hours to split by")
    shares = {s: int(cents * h / hours) for s, h in servers_hours.items()}
    remainder = cents - sum(shares.values())
    if remainder:
        top = max(shares, key=lambda s: servers_hours[s])
        shares[top] += remainder
    return {s: c / 100 for s, c in shares.items()}

if __name__ == "__main__":
    tips = float(sys.argv[1])
    hrs = {}
    for pair in sys.argv[2:]:
        name, h = pair.split("=")
        hrs[name] = float(h)
    for s, amt in split_tips(tips, hrs).items():
        print(f"{s:<24}{amt:>10.2f}")
EOF
